import React, { useState, useRef } from 'react';

function IntroOverlay({ onComplete }) {
  const [started, setStarted] = useState(false);
  const [showMessage, setShowMessage] = useState(false);
  const audioRefs = useRef({
    sound1: new Audio('/assets/audio/sound1.mp3'),
    sound2: new Audio('/assets/audio/sound2.mp3')
  });

  const startSequence = async () => {
    setStarted(true);
    // Play sound1
    await audioRefs.current.sound1.play();
    await new Promise(resolve => setTimeout(resolve, 3000));

    // Play sound2
    await audioRefs.current.sound2.play();
    await new Promise(resolve => setTimeout(resolve, 2000));

    // Show message
    setShowMessage(true);
    await new Promise(resolve => setTimeout(resolve, 4000));

    // Complete intro
    onComplete();
  };

  React.useEffect(() => {
    return () => {
      // Cleanup audio on unmount
      Object.values(audioRefs.current).forEach(audio => {
        audio.pause();
        audio.currentTime = 0;
      });
    };
  }, []);

  return (
    <div className="fixed inset-0 bg-black z-50 flex items-center justify-center">
      {!started ? (
        <button
          className="bg-gray-800 text-white px-8 py-4 rounded-lg text-2xl shadow-lg hover:bg-gray-700 transition"
          onClick={startSequence}
        >
          เริ่มต้น
        </button>
      ) : (
        <div className={`text-center transition-opacity duration-1000 ${showMessage ? 'opacity-100' : 'opacity-0'}`}>
          <h2 className="text-4xl font-bold text-white mb-4">
            ชีวิตสั้นกว่าที่คิด...
          </h2>
          <p className="text-2xl text-gray-300">
            วางแผนวันสุดท้ายไว้ก่อนดีไหม?
          </p>
        </div>
      )}
    </div>
  );
}

export default IntroOverlay;
